import { Injectable } from '@angular/core';
import { CanActivate } from '@angular/router';

// ❌ OLD: A class guard must be decorated, provided, and constructed
// through DI. For a single boolean check this is heavy boilerplate.
@Injectable({ providedIn: 'root' }) // ❌ OLD: registration required
export class AuthGuard implements CanActivate {
  constructor(private auth: AuthService) {} // ❌ OLD: constructor DI

  canActivate() {
    return this.auth.isLoggedIn();
  }
}

// Route: { path: 'admin', canActivate: [AuthGuard] }

import { inject } from '@angular/core';
import { CanActivateFn } from '@angular/router';

// ✅ NEW: A plain function. inject() resolves AuthService from the
// current injection context (guards run inside one). No class, no
// @Injectable, no constructor — tree-shakable and testable.
export const authGuard: CanActivateFn = () => {
  return inject(AuthService).isLoggedIn(); // ✅ NEW: inject() works here
};

// Route: { path: 'admin', canActivate: [authGuard] }

